<script setup>
import {ref,computed,onMounted,watch,nextTick} from 'vue';
import {state,t,go,api,brandLogo,bootstrap,date} from '../store';
import Icon from './Icon.vue';
import LandingPage from './LandingPage.vue';
import PublicNavigation from './PublicNavigation.vue';
const form=ref({name:'',email:'',password:'',password_confirmation:''}),busy=ref(false),error=ref(''),errors=ref({}),show=ref(false),certificate=ref(null),verifyToken=ref('');
const copy=(en,id)=>state.language==='id'?id:en;
function fieldError(field){return (errors.value[field]||[]).join(' ')}
function clearFieldError(field){delete errors.value[field]}
const publicHeaderHeight=ref(0);
const isRegister=computed(()=>state.path==='/register'),isAuth=computed(()=>['/login','/register'].includes(state.path)),isVerify=computed(()=>state.path.startsWith('/verify'));
const requestedTestType=computed(()=>{const code=new URLSearchParams(state.query).get('test_type');return ['practice','placement','certification'].includes(code)?code:''});
const authSwitchHref=computed(()=>(isRegister.value?'/login':'/register')+(requestedTestType.value?'?test_type='+requestedTestType.value:''));
async function authenticate(){if(busy.value)return;busy.value=true;error.value='';errors.value={};const testType=requestedTestType.value;try{await api(isRegister.value?'/register':'/login',{method:'POST',body:form.value});await bootstrap();go(testType&&state.user?.role==='participant'?'/tests?test_type='+testType:'/dashboard')}catch(e){error.value=e.message;errors.value=e.data?.errors||{};await nextTick();document.querySelector('.stack-form [aria-invalid="true"]')?.focus()}finally{busy.value=false}}
async function verify(){if(!verifyToken.value.trim())return;busy.value=true;error.value='';certificate.value=null;try{const response=await api('/verify/'+encodeURIComponent(verifyToken.value.trim()));certificate.value={...response.certificate,status:response.status,valid:response.status==='valid'}}catch(e){if(e.data?.status==='not_found')certificate.value={status:'not_found',valid:false};else error.value=e.message}finally{busy.value=false}}
function loadVerification(){if(isVerify.value){verifyToken.value=state.path.split('/')[2]||'';if(verifyToken.value)verify()}}
onMounted(loadVerification);
watch(()=>state.path,()=>{error.value='';errors.value={};show.value=false;loadVerification()});
</script>
<template>
<div class="public-shell" :style="{'--public-header-height':publicHeaderHeight+'px'}">
 <PublicNavigation :auth-page="isAuth" @height="publicHeaderHeight=$event"/>
 <main v-if="isAuth" id="main-content" tabindex="-1" class="auth-layout">
  <div class="auth-visual"><div class="auth-visual-copy"><span class="banner-label"><span></span>{{t('trusted')}}</span><h1>{{t('tagline')}}</h1><p>{{t('heroSub')}}</p><img src="/brand/journey.svg" alt="Open book representing a new learning journey"><div class="auth-quote"><span aria-hidden="true">&#8220;</span><p>Bahasa adalah jendela dunia.<small>Language is a window to the world.</small></p></div></div><div class="banner-orbit orbit-one"></div></div>
  <div class="auth-form-wrap">
   <button class="text-button auth-back" @click="go('/')"><Icon name="ArrowLeft" :size="18"/>{{t('home')}}</button>
   <span class="auth-mini-icon"><Icon :name="isRegister?'UserRoundPlus':'LogIn'" :size="27"/></span><div class="eyebrow">{{isRegister?copy('YOUR NEXT CHAPTER','LANGKAH BARU ANDA'):copy('GOOD TO SEE YOU AGAIN','SELAMAT DATANG KEMBALI')}}</div><h1>{{isRegister?t('register'):t('welcomeBack')}}</h1><p>{{isRegister?copy('Take the first step toward your Indonesian language goals.','Mulai langkah pertama menuju tujuan bahasa Indonesia Anda.'):copy('Your Indonesian journey is ready to continue.','Perjalanan bahasa Indonesia Anda siap dilanjutkan.')}}</p>
   <form @submit.prevent="authenticate" class="stack-form" :aria-busy="busy">
    <label v-if="isRegister" for="auth-name">{{t('name')}}<input id="auth-name" v-model="form.name" autocomplete="name" required maxlength="120" :disabled="busy" :placeholder="t('name')" :aria-invalid="!!fieldError('name')" :aria-describedby="fieldError('name')?'auth-name-error':undefined" @input="clearFieldError('name')"><span v-if="fieldError('name')" id="auth-name-error" class="auth-field-error">{{fieldError('name')}}</span></label>
    <label for="auth-email">{{t('email')}}<input id="auth-email" type="email" v-model="form.email" autocomplete="email" required maxlength="254" :disabled="busy" placeholder="you@example.com" :aria-invalid="!!fieldError('email')" :aria-describedby="fieldError('email')?'auth-email-error':undefined" @input="clearFieldError('email')"><span v-if="fieldError('email')" id="auth-email-error" class="auth-field-error">{{fieldError('email')}}</span></label>
    <div class="auth-password-field"><label for="auth-password">{{t('password')}}</label><div class="password-input"><input id="auth-password" :type="show?'text':'password'" v-model="form.password" :autocomplete="isRegister?'new-password':'current-password'" required :minlength="isRegister?8:undefined" :disabled="busy" placeholder="&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;" :aria-invalid="!!fieldError('password')" :aria-describedby="fieldError('password')?'auth-password-error':undefined" @input="clearFieldError('password')"><button type="button" class="icon-button" :disabled="busy" @click="show=!show" :aria-pressed="show" :aria-label="show?copy('Hide password','Sembunyikan password'):t('showPassword')"><Icon :name="show?'EyeOff':'Eye'" :size="20"/></button></div><span v-if="fieldError('password')" id="auth-password-error" class="auth-field-error">{{fieldError('password')}}</span></div>
    <label v-if="isRegister" for="auth-password-confirmation">{{copy('Confirm password','Konfirmasi password')}}<input id="auth-password-confirmation" type="password" v-model="form.password_confirmation" autocomplete="new-password" required minlength="8" :disabled="busy" placeholder="&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;" :aria-invalid="!!fieldError('password_confirmation')" :aria-describedby="fieldError('password_confirmation')?'auth-password-confirmation-error':undefined" @input="clearFieldError('password_confirmation')"><span v-if="fieldError('password_confirmation')" id="auth-password-confirmation-error" class="auth-field-error">{{fieldError('password_confirmation')}}</span></label>
    <div v-if="error" class="inline-error" role="alert">{{error}}</div><button class="button full" :disabled="busy"><Icon v-if="busy" name="LoaderCircle" class="auth-spinner" :size="20"/>{{busy?t('loading'):isRegister?t('register'):t('login')}}<Icon v-if="!busy" name="ArrowRight" :size="18"/></button>
   </form>
   <p class="auth-switch">{{isRegister?copy('Already have an account?','Sudah memiliki akun?'):copy('New to INBAF?','Baru di INBAF?')}} <a :href="authSwitchHref" @click.prevent="go(authSwitchHref)">{{isRegister?t('login'):t('register')}}</a></p><div class="auth-security"><Icon name="ShieldCheck" :size="18"/>{{t('secure')}}</div>
  </div>
 </main>
 <main v-else-if="isVerify" id="main-content" tabindex="-1" class="verification-page">
  <span class="auth-mini-icon"><Icon name="BadgeCheck" :size="30"/></span><div class="eyebrow">{{t('verification')}}</div><h1>{{t('verify')}}</h1><p>{{t('verifyText')}}</p>
  <form @submit.prevent="verify" class="verify-form" :aria-busy="busy"><label class="verify-token-label" for="verify-token">{{t('verifyToken')}}<input id="verify-token" :aria-label="copy('Certificate token','Token sertifikat')" v-model="verifyToken" :placeholder="t('verifyToken')" required :disabled="busy" autocomplete="off" spellcheck="false"></label><button class="button" :disabled="busy"><Icon v-if="busy" name="LoaderCircle" class="auth-spinner" :size="20"/>{{busy?t('loading'):t('verify')}}<Icon v-if="!busy" name="Search" :size="18"/></button></form>
  <div v-if="error" class="inline-error" role="alert">{{error}}</div><p v-if="busy" class="verify-loading" role="status">{{t('loading')}}</p>
  <section v-if="certificate" class="panel verified-card" aria-live="polite" aria-labelledby="verification-result-title"><span class="verified-mark" :class="{invalid:certificate.valid===false||certificate.status==='revoked'||certificate.status==='expired'}"><Icon :name="certificate.valid===false||['revoked','expired'].includes(certificate.status)?'ShieldX':'ShieldCheck'" :size="37"/></span><h2 id="verification-result-title">{{certificate.valid===false||['revoked','expired'].includes(certificate.status)?t('invalid'):t('verified')}}</h2><span class="badge" :class="certificate.valid===false?'red':'green'">{{certificate.status||'Valid'}}</span>
   <p v-if="certificate.status==='not_found'" class="verification-empty">{{copy('No certificate matches this token. Check the code and try again.','Tidak ada sertifikat dengan token ini. Periksa kode dan coba lagi.')}}</p>
   <dl v-else><div v-for="(value,key) in {[copy('Participant','Peserta')]:certificate.holder_name||certificate.participant_name||certificate.participant?.name||certificate.user?.name,[copy('Certificate number','Nomor sertifikat')]:certificate.number||certificate.certificate_number,[copy('Assessment','Tes')]:certificate.exam_package||certificate.package_name||certificate.package?.name,[t('score')]:certificate.total_score!==undefined?certificate.total_score+' / '+(certificate.score_max||100):certificate.score,[t('level')]:certificate.level,[copy('Issued on','Diterbitkan')]:date(certificate.issued_at),[copy('Valid until','Berlaku hingga')]:date(certificate.expires_at)}" :key="key"><dt>{{key}}</dt><dd>{{typeof value==='object'?value?.name:value??'\u2014'}}</dd></div></dl>
   <p v-if="certificate.revocation_reason" class="inline-error">{{certificate.revocation_reason}}</p>
  </section>
 </main>
 <LandingPage v-else/>
 <footer v-if="isAuth||isVerify" class="public-footer"><img :src="brandLogo()" alt="INBAF"><p>{{state.settings.footer||t('footer')}}</p><span>&copy; {{new Date().getFullYear()}} {{state.settings.system_name||'INBAF'}}</span><a href="/verify" @click.prevent="go('/verify')">{{t('verify')}}<Icon name="ArrowUpRight" :size="18"/></a></footer>
</div>
</template>
<style scoped>
#main-content{scroll-margin-top:calc(var(--public-header-height,6rem) + 1rem)}

.public-shell{min-width:0}.auth-layout{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:48px;max-width:1440px;padding-inline:32px;align-items:stretch;margin-block:32px 64px}.auth-visual{background:var(--surface-alt);border:1px solid var(--border);padding:40px;min-width:0}.auth-visual h1{color:var(--heading);font-size:clamp(2rem,3.2vw,2.75rem);line-height:1.35}.auth-visual p,.auth-quote p,.auth-quote small{color:var(--muted);font-size:1.125rem;line-height:1.8}.auth-visual .banner-label,.auth-quote>span{color:var(--color-accent)}.auth-visual img{max-width:100%;width:300px}.auth-form-wrap{max-width:440px;min-width:0;padding-block:16px;align-self:center}.auth-form-wrap>h1{font-size:clamp(1.75rem,2.8vw,2.25rem);line-height:1.4;overflow-wrap:anywhere}.auth-form-wrap>p{font-size:1.125rem;line-height:1.8}.auth-form-wrap>.eyebrow{font-size:1rem;line-height:1.7;overflow-wrap:anywhere}.auth-mini-icon{background:var(--blue-soft);color:var(--color-accent);border-color:var(--border)}.auth-form-wrap .stack-form{gap:20px;margin-top:28px}.stack-form>label,.auth-password-field>label{font-size:1.125rem;line-height:1.6;color:var(--text);font-weight:600;min-width:0}.stack-form :is(input,.button){min-height:48px;width:100%;min-width:0;max-width:100%;font-size:1.125rem}.stack-form .button,.auth-back{white-space:normal}.password-input{margin-top:8px}.password-input>button{width:44px;height:44px;right:4px;top:50%;transform:translateY(-50%)}.password-input>input{padding-right:56px!important}.auth-field-error{display:block;font-size:1rem;font-weight:500;color:var(--danger,var(--color-danger));line-height:1.6;margin-top:8px;overflow-wrap:anywhere}.auth-switch{font-size:1.125rem!important;line-height:1.8}.auth-switch>a{color:var(--color-accent);display:inline-block;min-height:44px;padding:4px}.auth-security{font-size:1.0625rem;color:var(--muted);line-height:1.7;align-items:flex-start}.auth-security>svg{flex-shrink:0;margin-top:4px}.verification-page{max-width:800px;padding:48px 24px 72px;min-width:0}.verification-page>h1{font-size:clamp(1.75rem,3.2vw,2.25rem);line-height:1.4;overflow-wrap:anywhere}.verification-page>p{font-size:1.125rem;line-height:1.8}.verify-form{align-items:flex-end;gap:16px;min-width:0;text-align:left}.verify-token-label{flex:1;display:grid;gap:8px;min-width:0;font-size:1.125rem;line-height:1.6;font-weight:600}.verify-token-label>input{min-width:0;max-width:100%;width:100%;min-height:48px;font-size:1.125rem}.verify-form>.button{font-size:1.125rem;min-height:48px;white-space:normal}.verified-card{padding:32px;min-width:0}.verified-card>h2{font-size:1.5rem;line-height:1.5;overflow-wrap:anywhere}.verified-card dl>div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr);gap:16px;font-size:1.125rem;line-height:1.75}.verified-card :is(dt,dd){min-width:0;overflow-wrap:anywhere}.verified-card dd{margin:0}.verified-mark{background:var(--blue-soft);color:var(--color-accent);border-color:var(--border)}.verified-mark.invalid{color:var(--danger,var(--color-danger));background:var(--surface-alt);border-color:var(--border)}.verification-empty{font-size:1.125rem;line-height:1.8;color:var(--muted);margin-top:24px}.verify-loading{color:var(--muted)}.public-footer{flex-wrap:wrap;font-size:1.0625rem;line-height:1.7}.public-footer p{font-size:1.0625rem}.public-footer>a{min-height:44px;white-space:normal;max-width:100%}.inline-error{overflow-wrap:anywhere}.public-shell :is(button,input,a):focus-visible{outline:3px solid var(--color-accent);outline-offset:3px}.auth-spinner{animation:auth-spin 1s linear infinite}@keyframes auth-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.auth-spinner{animation:none}}
@media(max-width:1000px){.auth-layout{gap:32px;padding-inline:24px}.auth-visual{padding:28px}.auth-visual h1{font-size:2rem}.auth-visual img{width:240px}}
@media(max-width:800px){.auth-layout{grid-template-columns:minmax(0,1fr);margin-block:24px 40px}.auth-visual{display:none}.auth-form-wrap{max-width:480px;width:100%;justify-self:center}.auth-back{margin-bottom:24px}}
@media(max-width:600px){.auth-layout{padding-inline:20px;display:grid}.auth-form-wrap{max-width:100%}.auth-form-wrap .button{font-size:1.125rem;min-height:48px}.verification-page{padding:32px 20px 48px}.verify-form{flex-direction:column;align-items:stretch}.verify-form>.button{width:100%}.verified-card{padding:24px 20px}.verified-card dl>div{grid-template-columns:minmax(0,1fr);gap:4px;padding-block:16px}.verified-card dd{text-align:left}.public-footer{padding:24px 20px;gap:16px}.public-footer>span{margin-left:0;overflow-wrap:anywhere}.public-footer>a{justify-content:flex-start;text-align:left}.auth-security{justify-content:flex-start}}
.public-shell .auth-layout,.public-shell .auth-form-wrap,.public-shell .verification-page,.public-shell .public-footer{background:var(--surface);color:var(--text)}.public-shell .auth-form-wrap{padding:24px 0}.public-shell .auth-form-wrap h1,.public-shell .verification-page h1,.public-shell .verified-card h2{color:var(--heading)}.public-shell .auth-form-wrap :is(label,.eyebrow),.public-shell .verify-token-label{color:var(--text)}.public-shell .auth-back{color:var(--muted)!important}.public-shell .auth-back:hover{color:var(--color-accent)!important}.public-shell .auth-form-wrap input,.public-shell .verify-form input{background:var(--surface)!important;border-color:var(--border)!important;color:var(--text)!important}.public-shell .auth-form-wrap input::placeholder,.public-shell .verify-form input::placeholder{color:var(--muted)!important}.public-shell .auth-form-wrap input:focus,.public-shell .verify-form input:focus{border-color:var(--color-accent)!important;box-shadow:none!important}.public-shell .auth-form-wrap .icon-button{color:var(--muted)}.public-shell .auth-switch>a{color:var(--color-accent)}.public-shell .verified-card{background:var(--surface-alt)!important;border-color:var(--border)!important;color:var(--text);width:100%;max-width:640px}.public-shell .verified-card dt{color:var(--muted)}.public-shell .verified-card dd{color:var(--text)}.public-shell .public-footer{border-color:var(--border)}.public-shell .public-footer>img{width:112px;height:auto;max-height:40px;object-fit:contain;object-position:left center;margin:0}.public-shell .public-footer a{color:var(--color-accent)}
</style>

